{
  "name": "task-manager",
  "version": "1.0.0",
  "description": "Small task management library for Frontier Verifier benchmark",
  "type": "module",
  "license": "MIT",
  "main": "src/index.ts",
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/bun": "latest"
  }
